            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            if (limit != null && due != null && due.compareTo(limit) > 0
                    && settings.role(claim.getSheetId(), change.user()) == Role.CLERK) {
                throw new ClaimStatusRefusedException("A clerk cannot settle a claim whose due is over the clerk limit");
            }
        }
        claim.setStatus(change.action().to());
        if (change.action() == ClaimAction.OPEN) {
            claim.setNumber(numbers.next(claim));
            claim.setOpenedBy(change.user());
        }
        if (change.action() == ClaimAction.SETTLE) {
            claim.setDue(due);
        }
    }
}
package net.officefloor.hq.app.claim;

/** A status change asked of a claim: the status it moves to, the statuses it may move from, and
 *  the audit event it writes. */
public enum ClaimAction {
    OPEN(ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.DRAFT),
    SETTLE(ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.OPEN),
    VOID(ClaimStatus.VOID, "CLAIM_VOIDED", ClaimStatus.DRAFT, ClaimStatus.OPEN);

    private final ClaimStatus to;
    private final String event;
    private final ClaimStatus[] from;

    ClaimAction(ClaimStatus to, String event, ClaimStatus... from) {
        this.to = to;
        this.event = event;
        this.from = from;
    }

    public ClaimStatus to() { return to; }
    public String event() { return event; }

    public boolean allowedFrom(ClaimStatus status) {
        for (ClaimStatus s : from) {
            if (s == status) return true;
        }
        return false;
    }
}
package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT → OPEN → SETTLED, and DRAFT or OPEN → VOID. */
public enum ClaimStatus {
    DRAFT, OPEN, SETTLED, VOID;

    /** Only OPEN and SETTLED claims count toward claimed, due-total and every total. */
    public boolean counts() {
        return this == OPEN || this == SETTLED;
    }
}
package net.officefloor.hq.app.claim;

/** A validated status change body. */
public record ClaimStatusChange(ClaimAction action, String user) {
}
package net.officefloor.hq.app.claim;

/** Body of a claim status change: the action (open, settle or void) and who takes it. */
public record ClaimStatusRequest(String action, String user) {
}
package net.officefloor.hq.app.claim;

import java.util.Locale;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaimStatus {
    public void validate(@RequestBody ClaimStatusRequest request, Out<ClaimStatusChange> body, Out<Actor> actor)
            throws InvalidSheetRequestException {
        String action = request == null || request.action() == null ? "" : request.action().trim();
        try {
            actor.set(new Actor(request.user()));
            body.set(new ClaimStatusChange(ClaimAction.valueOf(action.toUpperCase(Locale.ROOT)), request.user()));
        } catch (IllegalArgumentException e) {
            throw new InvalidSheetRequestException("Not a claim action (open, settle or void): " + action);
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Runs after the claim is saved, so a refused status change writes no audit line. */
public class RecordClaimStatusChanged {
    public void record(@Val ClaimStatusChange change, @Val Claim claim, People people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.record(change.action().event() + " sheet=" + claim.getSheetId() + " by=" + change.user()
                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
                + " date=" + claim.getDate() + (claim.getNumber() != null ? " number=" + claim.getNumber() : "")
                + (change.action() == ClaimAction.SETTLE
                        ? " due=" + (claim.getDue() != null ? claim.getDue().toPlainString() : "n/a") : ""));
    }
}
# Open, settle or void a claim. Validate before Load so an unknown action is a 400, not a 404;
# a change the claim's status does not allow is a 409 and writes nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimStatus
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused change writes no line.
record:
  class: net.officefloor.hq.app.claim.RecordClaimStatusChanged
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]

